corporate_design.toad_component_blueprint:
canvas {
  size: 880px 600px;
  fill: #0B0C10;
  font-family: "Didot, serif";
}

>gold = #C5A059;
>silver = #E2E8F0;

rect #watchCard {
  at: center of canvas;
  size: 780px 500px;
  fill: #101217;
  stroke: >gold;
  stroke-width: 1px;
}

text #brandHeader {
  at: top center of #watchCard offset 0px 48px;
  content: "VALMONT & CIE. • GENÈVE";
  font-size: 15px;
  font-weight: 600;
  color: >gold;
}

text #modelTitle {
  at: below #brandHeader offset 20px;
  content: "CHRONOGRAPHE TOURBILLON";
  font-size: 32px;
  font-weight: 700;
  color: >silver;
}
